        className={cn("flex flex-col items-center gap-0.5 py-2 text-[11px]", current === item ? "font-medium text-foreground" : "text-muted-foreground")}>
        <item.icon className={cn("size-5", current === item && "text-brand")} aria-hidden="true" />{item.label}
      </Link>)}
      <button type="button" onClick={() => setMenu(true)} aria-haspopup="dialog" className="flex flex-col items-center gap-0.5 py-2 text-[11px] text-muted-foreground"><Menu className="size-5" aria-hidden="true" />More</button>
    </nav>
    <Modal open={menu} onClose={() => setMenu(false)} label="Navigation" className="inset-x-0 bottom-0 top-auto w-full lg:hidden">
      <nav aria-label="All pages" className="max-h-[80vh] w-full space-y-5 overflow-y-auto rounded-t-2xl border-t border-border bg-card p-4 pb-[calc(1rem+env(safe-area-inset-bottom))]">
        <NavSections current={current} shell={shell} onNavigate={() => setMenu(false)} />
        <div className="border-t border-border pt-3"><NavLink item={settingsItem} current={current} shell={shell} onNavigate={() => setMenu(false)} /></div>
      </nav>
    </Modal>
    {palette && <Suspense fallback={<CommandPalette commands={commands} {...paletteProps} />}><AccountCommands shell={shell} base={commands} {...paletteProps} /></Suspense>}
    <ShortcutHelp open={help} onClose={() => setHelp(false)} shortcuts={shortcuts} />
  </div>;
}
import * as React from "react";
import { cva, type VariantProps } from "class-variance-authority";
import { cn } from "@/lib/utils";

const buttonVariants = cva(
  "inline-flex items-center justify-center gap-2 whitespace-nowrap rounded-md text-sm font-medium transition-colors focus-visible:outline-none disabled:pointer-events-none disabled:opacity-50 [&_svg]:size-4 [&_svg]:shrink-0",
  {
    variants: {
      variant: {
        default: "bg-primary text-primary-foreground hover:opacity-90",
        outline: "border border-border bg-background hover:bg-accent hover:text-accent-foreground",
        secondary: "bg-muted text-foreground hover:opacity-80",
        ghost: "hover:bg-accent hover:text-accent-foreground",
      },
      size: {
        default: "h-9 px-4 py-2",
        sm: "h-8 rounded-md px-3 text-xs",
        lg: "h-10 rounded-md px-8",
      },
    },
    defaultVariants: { variant: "default", size: "default" },
  },
);

interface ButtonProps
  extends React.ButtonHTMLAttributes<HTMLButtonElement>,
    VariantProps<typeof buttonVariants> {
  asChild?: boolean;
}

export const Button = React.forwardRef<HTMLButtonElement, ButtonProps>(
  ({ className, variant, size, asChild, children, ...props }, ref) => {
    if (asChild && React.isValidElement(children)) {
      return React.cloneElement(children as React.ReactElement<{ className?: string }>, {
        // @ts-expect-error - ref forwarding into slot child
        ref,
        className: cn(buttonVariants({ variant, size }), (children as React.ReactElement<{ className?: string }>).props.className, className),
      });
    }
    return (
      <button ref={ref} className={cn(buttonVariants({ variant, size }), className)} {...props}>
        {children}
      </button>
    );
  },
);
Button.displayName = "Button";
import type { Metadata } from "next";
import "./globals.css";
import { Suspense } from "react";
import { Providers } from "@/components/providers";
import { AppShell, type ShellData } from "@/components/app-shell";
import { cookies } from "next/headers";
import { ThemePreference } from "@/components/theme-preference";
import { hasSupabase } from "@/lib/env";
import { requireWorkspace } from "@/lib/auth";

export const metadata: Metadata = {
  title: "Moneo — Personal Finance Workspace",
  description: "Understand your money, plan decisions, and build reusable financial tools with AI.",
};

type Theme = "light" | "dark" | "system";

// Streams in after the shell so the saved theme never blocks the first paint or loading.tsx.
async function WorkspaceTheme({ fallback }: { fallback: Theme }) {
  let theme = fallback;
  try { theme = (await requireWorkspace()).settings.theme; } catch { /* signed out or no workspace: keep the cookie theme */ }
  return <ThemePreference preference={theme} />;
}

// Sidebar counts and palette accounts. Not awaited: the shell streams them in behind <Suspense>.
// ponytail: root layouts don't re-render on client navigation, so counts refresh on reload or router.refresh().
async function loadShellData(): Promise<ShellData> {
  try {
    const { supabase, workspace } = await requireWorkspace();
    const pending = (table: string) => supabase.from(table).select("id", { count: "exact", head: true }).eq("workspace_id", workspace.id);
    const [accounts, recurring, reviews, jobs] = await Promise.all([
      supabase.from("accounts").select("id, name").eq("workspace_id", workspace.id).is("archived_at", null).order("name").limit(200),
      pending("recurring_series").eq("status", "pending"),
      pending("organization_reviews").eq("status", "pending"),
      pending("background_jobs").in("status", ["queued", "running"]),
    ]);
    return {
      accounts: accounts.data ?? [],
      counts: { "/money/recurring": recurring.count ?? 0, "/money/organization": reviews.count ?? 0, "/ai/activity": jobs.count ?? 0 },
    };
  } catch { return null; }
}

export default async function RootLayout({ children }: { children: React.ReactNode }) {
  const cookieTheme = (await cookies()).get("moneo-theme")?.value;
  const theme: Theme = cookieTheme === "light" || cookieTheme === "dark" ? cookieTheme : "system";
  return (
    <html lang="en" data-theme={theme} suppressHydrationWarning>
      <body className="min-h-screen bg-background font-sans text-foreground antialiased">
        {hasSupabase() ? <Suspense fallback={<ThemePreference preference={theme} />}><WorkspaceTheme fallback={theme} /></Suspense> : <ThemePreference preference={theme} />}
        <Providers><AppShell shell={hasSupabase() ? loadShellData() : Promise.resolve(null)}>{children}</AppShell></Providers>
      </body>
    </html>
  );
}
"use client";

import { useEffect } from "react";

export function ThemePreference({ preference }: { preference: "light" | "dark" | "system" }) {
  useEffect(() => {
    const media = window.matchMedia("(prefers-color-scheme: dark)");
    const apply = () => { document.documentElement.dataset.theme = preference === "system" ? media.matches ? "dark" : "light" : preference; };
    apply();
    media.addEventListener("change", apply);
    return () => media.removeEventListener("change", apply);
  }, [preference]);
  return null;
}

