    <form action={createGoal} className="flex flex-wrap items-end gap-3 rounded-lg bg-muted/50 p-4"><input type="hidden" name="requestId" value={crypto.randomUUID()} /><input name="name" required maxLength={120} placeholder="Goal name" aria-label="Goal name" className={field} /><input name="target" required inputMode="decimal" p
  </section>;
