import Link from "next/link";
import { redirect } from "next/navigation";
import { z } from "zod";
import { Bot } from "lucide-react";
import { requireWorkspace } from "@/lib/auth";
import { TeamFlow } from "@/components/team-flow";
import { StartAgentRun } from "./start-run";

export default async function AgentRunsPage({ searchParams }: { searchParams: Promise<{ import?: string }> }) {
  let context: Awaited<ReturnType<typeof requireWorkspace>>;
  try { context = await requireWorkspace(); } catch { redirect("/login"); }
  const { supabase, workspace } = context;
  const importId = z.uuid().safeParse((await searchParams).import);
  if (importId.success) {
    const run = await supabase.from("agent_runs").select("id").eq("workspace_id", workspace.id).eq("import_id", importId.data).maybeSingle();
    if (run.data) redirect(`/ai/agents/${run.data.id}`);
  }
  const runs = await supabase.from("agent_runs").select("id, status, trigger, created_at, briefing").eq("workspace_id", workspace.id).order("created_at", { ascending: false }).limit(20);
  const counts = await supabase.from("agent_proposals").select("run_id, status").eq("workspace_id", workspace.id).eq("status", "proposed").limit(1000);
  const open = new Map<string, number>();
  for (const row of counts.data ?? []) open.set(row.run_id, (open.get(row.run_id) ?? 0) + 1);
  return <main className="mx-auto w-full max-w-5xl space-y-6 px-4 py-6 sm:px-8 lg:py-8">
    <header className="flex flex-wrap items-center gap-3">
      <div className="mr-auto"><h1 className="flex items-center gap-2 page-title"><Bot className="size-6 text-brand" aria-hidden="true" />Agent team</h1>
        <p className="text-sm text-muted-foreground">Specialised agents analyse your data after every import. They only propose; you decide.</p></div>
      <StartAgentRun />
    </header>
    {importId.success && <p role="status" className="rounded-lg bg-muted p-3 text-sm">The team starts as soon as that import&apos;s rows are in. <Link href={`/ai/agents?import=${importId.data}`} className="underline">Check again</Link></p>}
    <TeamFlow />
    <section aria-label="Runs" className="space-y-2">
      <h2 className="text-sm font-medium">Runs</h2>
      {runs.error && <p role="alert">Could not load runs: {runs.error.message}</p>}
      {!runs.data?.length && <p className="rounded-xl border border-dashed border-border p-5 text-center text-sm text-muted-foreground">No runs yet. <Link href="/import" className="underline">Import a statement</Link> or start one above.</p>}
      <ul className="divide-y divide-border rounded-xl border border-border bg-card">{(runs.data ?? []).map(run => <li key={run.id}><Link href={`/ai/agents/${run.id}`} className="flex flex-wrap items-center gap-3 px-4 py-3 hover:bg-muted">
        <span className="w-40 shrink-0 text-sm">{new Date(run.created_at).toLocaleString(workspace.locale)}</span>
        <span className="text-xs capitalize text-muted-foreground">{run.status} · {run.trigger}</span>
        <span className="min-w-0 flex-1 truncate text-sm text-muted-foreground">{run.briefing?.split("\n")[0]}</span>
        {open.get(run.id) ? <span className="rounded-full bg-brand/10 px-2 py-0.5 text-xs font-medium text-brand">{open.get(run.id)} to review</span> : null}
      </Link></li>)}</ul>
    </section>
  </main>;
}

  function decide(ids: string[], decision: "accept" | "reject") {
    if (!ids.length) return;
    setNotice("");
    startTransition(async () => {
      try {
        const outcomes = await decideAgentProposals(ids, decision);
        const failed = outcomes.filter(outcome => outcome.status === "failed");
        setNotice(failed.length ? `${failed.length} could not be applied: ${failed[0].error}` : `${outcomes.filter(outcome => outcome.status !== "unchanged").length} ${decision === "accept" ? "accepted" : "rejected"}.`);
        setSelected(new Set());
        await refresh();
        router.refresh();
      } catch (cause) { setNotice(cause instanceof Error ? cause.message : "Could not save decisions"); }
    });
  }

  const byAgent = new Map(run.tasks.map(task => [task.agent, task]));
  const lead = byAgent.get("lead");
  const decided = run.proposals.filter(item => item.result?.auto);
  const manual = run.proposals.filter(item => !item.result?.auto);
  const open = manual.filter(item => item.status === "proposed" || item.status === "failed");
  const reviewable = !active;
  const toggle = (id: string) => setSelected(current => { const next = new Set(current); if (next.has(id)) next.delete(id); else next.add(id); return next; });
  const kinds = (Object.keys(KIND_LABELS) as ProposalKind[]).filter(kind => manual.some(item => item.kind === kind));
  const model = run.model_status === "available" || run.model_status === "budget_exhausted" ? `Free model · ${run.model_calls}/${run.model_budget} calls`
    : run.model_status === "unknown" ? "Checking model…" : "Deterministic only (no free model)";

  return <div className="space-y-6">
    <header className="flex flex-wrap items-center gap-3">
      <div className="mr-auto min-w-0">
        <h1 className="flex items-center gap-2 page-title"><Bot className="size-6 text-brand" aria-hidden="true" />Agent team {pill(run.status)}</h1>
        <p className="text-sm text-muted-foreground">{run.trigger === "import" ? "Started when your import finished" : "Started manually"} · {new Date(run.created_at).toLocaleString(locale)} · {model}</p>
      </div>
      {active && <button type="button" onClick={() => void control("cancel")} className="inline-flex items-center gap-2 rounded-lg border border-border px-3 py-2 text-sm font-medium hover:bg-muted"><Square className="size-3.5" aria-hidden="true" />Stop</button>}
      {(run.status === "canceled" || run.status === "failed") && <button type="button" onClick={() => void control("resume")} className="inline-flex items-center gap-2 rounded-lg bg-primary px-3 py-2 text-sm font-medium text-primary-foreground hover:opacity-90"><Play className="size-3.5" aria-hidden
    </header>
    {run.tasks.length > 0 && <TeamFlow statuses={Object.fromEntries(run.tasks.map(task => [task.agent, task.status]))} finished={run.status === "completed"} />}
    {run.error && <p role="alert" className="rounded-lg bg-danger-soft p-3 text-sm text-danger">{run.error}</p>}

    {lead && <section aria-label="Lead agent" className="rounded-xl border border-border bg-card p-4">
      <div className="flex items-center gap-2"><StatusIcon status={lead.status} /><h2 className="text-sm font-semibold">Lead</h2><span className="text-xs text-muted-foreground">{lead.summary ?? lead.step}</span></div>
      <ol className="mt-2 grid gap-x-6 gap-y-1 text-xs text-muted-foreground sm:grid-cols-2">{lead.events.slice(-8).map((event, index) => <li key={`${event.at}-${index}`} className="flex gap-1.5"><ChevronRight className="mt-0.5 size-3 shrink-0" aria-hidden="true" />{event.text}</li>)}</ol>
    </section>}

    {WAVES.map((wave, index) => {
      const tasks = wave.map(agent => byAgent.get(agent)).filter((task): task is AgentTaskView => Boolean(task));
      return tasks.length > 0 && <section key={index} aria-label={WAVE_LABELS[index]} className="space-y-2">
        <h2 className="eyebrow">Wave {index + 1} · {WAVE_LABELS[index]}</h2>
        <div className="grid gap-3 sm:grid-cols-2 xl:grid-cols-4">{tasks.map(task => <AgentCard key={task.agent} task={task} />)}</div>
      </section>;
    })}
    {!run.tasks.length && <p role="status" className="flex items-center gap-2 text-sm text-muted-foreground"><LoaderCircle className="size-4 animate-spin" aria-hidden="true" />The lead is planning the work…</p>}

    {run.briefing && <section aria-label="Briefing" className="rounded-xl border border-brand/40 bg-card p-5">
      <h2 className="flex items-center gap-2 text-sm font-medium"><Sparkles className="size-4 text-brand" aria-hidden="true" />Briefing</h2>
      <div className="mt-2 space-y-2 text-sm leading-relaxed">{run.briefing.split(/\n{2,}/).map(paragraph => <p key={paragraph}>{paragraph}</p>)}</div>
      <p className="mt-2 text-xs text-muted-foreground">Every figure comes from application code; the writer is only allowed to repeat them.</p>
    </section>}

    {decided.length > 0 && <section aria-labelledby="decided-heading" className="space-y-2">
